    }

    h2 {
        font-size: 1.25rem;
    }

    .section-container {
        padding: 0 var(--spacing-sm);
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .carousel-control {
        width: 32px;
        height: 32px;
        font-size: 1.2rem;
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .toast {
        left: var(--spacing-sm);
        right: var(--spacing-sm);
        bottom: var(--spacing-sm);
