+    cursor: pointer;
+    border: none;
+}
+
+input, textarea, select {
+    font-family: inherit;
+}
+
+/* ========================================
+   Utility Classes
+   ======================================== */
+
+.sr-only {
+    position: absolute;
+    width: 1px;
+    height: 1px;
+    padding: 0;
+    margin: -1px;
+    overflow: hidden;
+    clip: rect(0, 0, 0, 0);
+    white-space: nowrap;
+    border-width: 0;
+}
+
+.skip-link {
+    position: absolute;
+    top: -40px;
+    left: 0;
+    background-color: var(--color-accent);
+    color: var(--color-dark);
+    padding: var(--spacing-sm);
+    z-index: 100;
+    text-decoration: none;
+    font-weight: 700;
+}
+
+.skip-link:focus {
+    top: 0;
+}
+
+.section-container {
+    max-width: 1400px;
+    margin: 0 auto;
+    padding: 0 var(--spacing-lg);
+}
+
+.section-header {
+    text-align: center;
+    margin-bottom: var(--spacing-2xl);
+}
+
+.section-header h2 {
+    margin-bottom: var(--spacing-sm);
+}
+
+.section-subtitle {
+    font-size: 1.1rem;
+    color: var(--color-text-secondary);
+}
+
+/* ========================================
+   Header & Navigation
+   ======================================== */
+
+.header {
+    background-color: var(--color-dark-secondary);
+    border-bottom: 1px solid var(--color-border);
+    position: sticky;
+    top: 0;
+    z-index: 50;
+    box-shadow: var(--shadow-md);
+}
+
+.header-container {
+    max-width: 1400px;
+    margin: 0 auto;
+    padding: var(--spacing-md) var(--spacing-lg);
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+}
+
+.logo h1 {
+    font-size: 1.75rem;
+    letter-spacing: 0.05em;
+    margin: 0;
+    color: var(--color-accent);
+    font-family: var(--font-family-accent);
+}
+
+.nav-primary ul {
+    display: flex;
+    list-style: none;
+    gap: var(--spacing-lg);
+}
+
+.nav-primary a {
+    color: var(--color-text);
+    font-size: 0.95rem;
+    font-weight: 500;
+    padding: var(--spacing-xs) var(--spacing-sm);
+    border-bottom: 2px solid transparent;
+    transition: var(--transition);
+}
+
+.nav-primary a:hover, .nav-primary a:focus {
+    border-bottom-color: var(--color-accent);
+    color: var(--color-accent);
+}
+
+.header-actions {
+    display: flex;
+    gap: var(--spacing-lg);
+    align-items: center;
+}
+
+.search-toggle, .cart-toggle {
+    background: none;
+    color: var(--color-text);
+    font-size: 1.25rem;
+    padding: var(--spacing-xs);
+    cursor: pointer;
+    transition: var(--transition);
+    position: relative;
+}
+
+.search-toggle:hover, .search-toggle:focus,
+.cart-toggle:hover, .cart-toggle:focus {
+    color: var(--color-accent);
+}
+
+.search-toggle:focus-visible, .cart-toggle:focus-visible {
+    outline: 2px solid var(--color-accent);
+    outline-offset: 2px;
+}
+
+.cart-count {
+    position: absolute;
+    top: -8px;
+    right: -8px;
+    background-color: var(--color-error);
+    color: white;
+    border-radius: 50%;
+    width: 20px;
+    height: 20px;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    font-size: 0.75rem;
+    font-weight: 700;
+}
+
+.search-overlay {
+    padding: var(--spacing-md) var(--spacing-lg);
+    border-top: 1px solid var(--color-border);
+    background-color: var(--color-dark-secondary);
+}
+
+.search-input {
+    width: 100%;
+    max-width: 400px;
+    padding: var(--spacing-sm);
+    background-color: var(--color-dark-tertiary);
+    border: 1px solid var(--color-border);
+    color: var(--color-text);
+    border-radius: 4px;
+    font-size: 1rem;
+}
+
+.search-input::placeholder {
+    color: var(--color-gray);
+}
+
+.search-input:focus {
+    outline: none;
+    border-color: var(--color-accent);
+    box-shadow: 0 0 0 2px rgba(212, 175, 55, 0.2);
+}
+
+/* ========================================
+   Main Content
+   ======================================== */
+
+main {
+    min-height: calc(100vh - 200px);
+}
+
+/* ========================================
+   Hero Section
+   ======================================== */
+
+.hero {
+    background: linear-gradient(135deg, var(--color-dark-tertiary) 0%, var(--color-dark) 100%);
+    padding: var(--spacing-2xl) var(--spacing-lg);
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: var(--spacing-2xl);
+    align-items: center;
+    border-bottom: 1px solid var(--color-border);
+    margin-bottom: var(--spacing-2xl);
+}
+
+.hero-content {
+    display: flex;
+    flex-direction: column;
+    justify-content: center;
+}
+
+.hero-content h2 {
+    font-size: 2.5rem;
+    margin-bottom: var(--spacing-md);
+    color: var(--color-accent);
+}
+
+.hero-content p {
+    font-size: 1.1rem;
+    margin-bottom: var(--spacing-lg);
+}
+
+.hero-visual {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+}
+
+.hero-image {
+    width: 100%;
+    max-width: 400px;
+    aspect-ratio: 1;
+    background: linear-gradient(135deg, var(--color-dark-secondary) 0%, var(--color-dark-tertiary) 100%);
+    border: 2px solid var(--color-border);
+    border-radius: 8px;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    font-size: 1.5rem;
+    color: var(--color-gray);
+}
+
+/* ========================================
+   Buttons
+   ======================================== */
+
+.cta-button {
+    padding: var(--spacing-sm) var(--spacing-lg);
+    border-radius: 4px;
+    font-weight: 600;
+    font-size: 0.95rem;
+    letter-spacing: 0.05em;
+    transition: var(--transition);
+    cursor: pointer;
+}
+
+.cta-button.primary {
+    background-color: var(--color-accent);
+    color: var(--color-dark);
+}
+
+.cta-button.primary:hover, .cta-button.primary:focus {
+    background-color: var(--color-accent-hover);
+    transform: translateY(-2px);
+    box-shadow: var(--shadow-lg);
+}
+
+.cta-button.primary:focus-visible {
+    outline: 2px solid var(--color-accent);
+    outline-offset: 2px;
+}
+
+.cta-button.secondary {
+    background-color: transparent;
+    color: var(--color-accent);
+    border: 1px solid var(--color-accent);
+}
+
+.cta-button.secondary:hover, .cta-button.secondary:focus {
+    background-color: rgba(212, 175, 55, 0.1);
+    border-color: var(--color-accent-hover);
+    color: var(--color-accent-hover);
+}
+
+.cta-button.secondary:focus-visible {
+    outline: 2px solid var(--color-accent);
+    outline-offset: 2px;
+}
+
+/* ========================================
+   Featured Products Section
+   ======================================== */
+
+.featured-section {
+    padding: var(--spacing-2xl) var(--spacing-lg);
+    background-color: var(--color-dark);
+}
+
+.products-carousel {
+    position: relative;
+    display: flex;
+    align-items: center;
+    gap: var(--spacing-lg);
+}
+
+.carousel-control {
+    position: absolute;
+    top: 50%;
+    transform: translateY(-50%);
+    background-color: rgba(212, 175, 55, 0.1);
+    color: var(--color-accent);
+    border: 1px solid var(--color-accent);
+    width: 40px;
+    height: 40px;
+    border-radius: 50%;
+    font-size: 1.5rem;
+    cursor: pointer;
+    transition: var(--transition);
+    z-index: 10;
+}
+
+.carousel-control:hover, .carousel-control:focus {
+    background-color: rgba(212, 175, 55, 0.2);
+    transform: translateY(-50%) scale(1.1);
+}
+
+.carousel-control:focus-visible {
+    outline: 2px solid var(--color-accent);
+    outline-offset: 2px;
+}
+
+.carousel-control.prev {
+    left: 0;
+}
+
+.carousel-control.next {
+    right: 0;
+}
+
+.products-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
+    gap: var(--spacing-lg);
+    flex: 1;
+}
+
+/* ========================================
+   Product Card
+   ======================================== */
+
+.product-card {
+    background-color: var(--color-dark-secondary);
+    border: 1px solid var(--color-border);
+    border-radius: 8px;
+    overflow: hidden;
+    transition: var(--transition);
+    display: flex;
+    flex-direction: column;
+}
+
+.product-card:hover, .product-card:focus-within {
+    border-color: var(--color-accent);
+    box-shadow: var(--shadow-lg);
+    transform: translateY(-4px);
+}
+
+.product-image {
+    width: 100%;
+    aspect-ratio: 1;
+    background-color: var(--color-dark-tertiary);
+    overflow: hidden;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+}
+
+.product-image img {
+    width: 100%;
+    height: 100%;
+    object-fit: cover;
+}
+
+.product-info {
+    padding: var(--spacing-lg);
+    flex: 1;
+    display: flex;
+    flex-direction: column;
+}
+
+.product-info h3 {
+    font-size: 1.1rem;
+    margin-bottom: var(--spacing-xs);
+    color: var(--color-text);
+}
+
+.product-category {
+    font-size: 0.85rem;
+    color: var(--color-text-secondary);
+    margin-bottom: var(--spacing-sm);
+    text-transform: uppercase;
+    letter-spacing: 0.05em;
+}
+
+.product-rating {
+    display: flex;
+    align-items: center;
+    gap: var(--spacing-xs);
+    margin-bottom: var(--spacing-sm);
+    font-size: 0.9rem;
+}
+
+.product-rating span:first-child {
+    color: var(--color-accent);
+    font-size: 1rem;
+}
+
+.rating-text {
+    color: var(--color-text-secondary);
+}
+
+.product-price {
+    display: flex;
+    align-items: center;
+    gap: var(--spacing-sm);
+    margin-bottom: var(--spacing-lg);
+    flex: 1;
+    align-items: flex-end;
+}
+
+.price-current {
+    font-size: 1.5rem;
+    font-weight: 700;
+    color: var(--color-accent);
+}
+
+.price-original {
+    font-size: 1rem;
+    color: var(--color-gray);
+    text-decoration: line-through;
+}
+
+.btn-add-cart {
+    padding: var(--spacing-sm);
+    background-color: var(--color-accent);
+    color: var(--color-dark);
+    border-radius: 4px;
+    font-weight: 600;
+    font-size: 0.95rem;
+    cursor: pointer;
+    transition: var(--transition);
+}
+
+.btn-add-cart:hover, .btn-add-cart:focus {
+    background-color: var(--color-accent-hover);
+    transform: translateY(-2px);
+}
+
+.btn-add-cart:focus-visible {
+    outline: 2px solid var(--color-accent);
+    outline-offset: 2px;
+}
+
+/* ========================================
+   Deals Section
+   ======================================== */
+
+.deals-section {
+    padding: var(--spacing-2xl) var(--spacing-lg);
+    background-color: var(--color-dark-secondary);
+}
+
+.deals-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
+    gap: var(--spacing-lg);
+}
+
+.deal-card {
+    background-color: var(--color-dark);
+    border: 1px solid var(--color-border);
+    border-radius: 8px;
+    padding: var(--spacing-lg);
+    position: relative;
+    transition: var(--transition);
+    overflow: hidden;
+}
+
+.deal-card:hover, .deal-card:focus-within {
+    border-color: var(--color-accent);
+    box-shadow: var(--shadow-lg);
+    transform: translateY(-4px);
+}
+
+.featured-deal {
+    grid-column: 1 / -1;
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: var(--spacing-lg);
+    align-items: center;
+}
+
+.deal-badge {
+    position: absolute;
+    top: var(--spacing-md);
+    left: var(--spacing-md);
+    background-color: var(--color-error);
+    color: white;
+    padding: var(--spacing-xs) var(--spacing-sm);
+    border-radius: 4px;
+    font-weight: 700;
+    font-size: 0.9rem;
+}
+
+.featured-deal .deal-badge {
+    position: static;
+    display: none;
+}
+
+.deal-image {
+    width: 100%;
+    aspect-ratio: 4 / 3;
+    background-color: var(--color-dark-tertiary);
+    border-radius: 4px;
+    overflow: hidden;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+}
+
+.deal-image img {
+    width: 100%;
+    height: 100%;
+    object-fit: cover;
+}
+
+.deal-content {
+    padding-top: var(--spacing-lg);
+}
+
+.deal-card h3 {
+    font-size: 1.25rem;
+    margin-bottom: var(--spacing-sm);
+}
+
+.deal-card p {
+    margin-bottom: var(--spacing-md);
+    color: var(--color-text-secondary);
+}
+
+.deal-timer {
+    font-size: 0.9rem;
+    color: var(--color-error);
+    font-weight: 600;
+    margin-bottom: var(--spacing-md);
+}
+
+/* ========================================
+   Editorial Section
+   ======================================== */
+
+.editorial-section {
+    padding: var(--spacing-2xl) var(--spacing-lg);
+    background-color: var(--color-dark);
+}
+
+.editorial-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
+    gap: var(--spacing-lg);
+}
+
+.featured-editorial {
+    grid-column: 1 / -1;
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: var(--spacing-lg);
+    align-items: center;
+}
+
+.editorial-card {
+    background-color: var(--color-dark-secondary);
+    border: 1px solid var(--color-border);
+    border-radius: 8px;
+    overflow: hidden;
+    transition: var(--transition);
+    display: flex;
+    flex-direction: column;
+}
+
+.editorial-card:hover, .editorial-card:focus-within {
+    border-color: var(--color-accent);
+    box-shadow: var(--shadow-lg);
+}
+
+.featured-editorial .editorial-image {
+    grid-column: 1;
+    grid-row: 1;
+}
+
+.featured-editorial .editorial-content {
+    grid-column: 2;
+    grid-row: 1;
+}
+
+.editorial-image {
+    width: 100%;
+    aspect-ratio: 3 / 2;
+    background-color: var(--color-dark-tertiary);
+    overflow: hidden;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+}
+
+.editorial-image img {
+    width: 100%;
+    height: 100%;
+    object-fit: cover;
+}
+
+.editorial-content {
+    padding: var(--spacing-lg);
+}
+
+.editorial-category {
+    display: inline-block;
+    font-size: 0.8rem;
+    text-transform: uppercase;
+    letter-spacing: 0.1em;
+    color: var(--color-accent);
+    margin-bottom: var(--spacing-sm);
+    font-weight: 600;
+}
+
+.editorial-card h3 {
+    margin-bottom: var(--spacing-sm);
+}
+
+.editorial-card h3 a {
+    color: var(--color-text);
+    transition: var(--transition);
+}
+
+.editorial-card:hover h3 a, .editorial-card:focus-within h3 a {
+    color: var(--color-accent);
+}
+
+.editorial-card p {
+    margin-bottom: var(--spacing-lg);
+}
+
+.editorial-meta {
+    display: flex;
+    flex-direction: column;
+    gap: var(--spacing-xs);
+    font-size: 0.9rem;
+    color: var(--color-text-secondary);
+}
+
+.author {
+    font-weight: 500;
+}
+
+/* ========================================
+   Newsletter Section
+   ======================================== */
+
+.newsletter-section {
+    padding: var(--spacing-2xl) var(--spacing-lg);
+    background: linear-gradient(135deg, var(--color-dark-secondary) 0%, var(--color-dark-tertiary) 100%);
+    border-top: 1px solid var(--color-border);
+    border-bottom: 1px solid var(--color-border);
+}
+
+.newsletter-content {
+    text-align: center;
+    max-width: 600px;
+    margin: 0 auto;
+}
+
+.newsletter-content h2 {
+    margin-bottom: var(--spacing-md);
+    color: var(--color-accent);
+}
+
+.newsletter-content p {
+    margin-bottom: var(--spacing-lg);
+    font-size: 1rem;
+}
+
+.newsletter-form {
+    margin-top: var(--spacing-lg);
+}
+
+.form-group {
+    display: flex;
+    gap: var(--spacing-sm);
+    margin-bottom: var(--spacing-md);
+}
+
+.form-group input {
+    flex: 1;
+    padding: var(--spacing-sm);
+    background-color: var(--color-dark);
+    border: 1px solid var(--color-border);
+    color: var(--color-text);
+    border-radius: 4px;
+    min-width: 0;
+}
+
+.form-group input::placeholder {
+    color: var(--color-gray);
+}
+
+.form-group input:focus {
+    outline: none;
+    border-color: var(--color-accent);
+    box-shadow: 0 0 0 2px rgba(212, 175, 55, 0.2);
+}
+
+.form-group input:invalid:not(:placeholder-shown) {
+    border-color: var(--color-error);
+}
+
+.form-group input:invalid:not(:placeholder-shown) ~ button {
+    opacity: 0.7;
+    cursor: not-allowed;
+}
+
+.form-group button {
+    white-space: nowrap;
+}
+
+.form-note {
+    font-size: 0.85rem;
+    color: var(--color-text-secondary);
+}
+
+/* ========================================
+   Footer
+   ======================================== */
+
+.footer {
+    background-color: var(--color-dark-secondary);
+    border-top: 1px solid var(--color-border);
+    padding: var(--spacing-2xl) var(--spacing-lg) var(--spacing-lg);
+}
+
+.footer-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
+    gap: var(--spacing-2xl);
+    margin-bottom: var(--spacing-2xl);
+    padding-bottom: var(--spacing-2xl);
+    border-bottom: 1px solid var(--color-border);
+}
+
+.footer-column h3 {
+    margin-bottom: var(--spacing-md);
+    color: var(--color-accent);
+}
+
+.footer-column ul {
+    list-style: none;
+}
+
+.footer-column a {
+    display: inline-block;
+    margin-bottom: var(--spacing-sm);
+    color: var(--color-text-secondary);
+    transition: var(--transition);
+}
+
+.footer-column a:hover, .footer-column a:focus {
+    color: var(--color-accent);
+    margin-left: 4px;
+}
+
+.footer-column p {
+    color: var(--color-text-secondary);
+    margin: 0;
+}
+
+.footer-bottom {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    flex-wrap: wrap;
+    gap: var(--spacing-lg);
+    font-size: 0.9rem;
+    color: var(--color-text-secondary);
+}
+
+.footer-legal {
+    list-style: none;
+    display: flex;
+    gap: var(--spacing-lg);
+}
+
+.footer-legal a {
+    color: var(--color-text-secondary);
+}
+
+.footer-legal a:hover, .footer-legal a:focus {
+    color: var(--color-accent);
+}
+
+/* ========================================
+   Toast Notification
+   ======================================== */
+
+.toast {
+    position: fixed;
+    bottom: var(--spacing-lg);
+    right: var(--spacing-lg);
+    padding: var(--spacing-md);
+    background-color: var(--color-dark-secondary);
+    border: 1px solid var(--color-border);
+    border-radius: 4px;
+    max-width: 300px;
+    opacity: 0;
+    pointer-events: none;
+    transition: var(--transition);
+    z-index: 1000;
+    box-shadow: var(--shadow-lg);
+}
+
+.toast.show {
+    opacity: 1;
+    pointer-events: auto;
+}
+
+.toast.success {
+    border-color: var(--color-success);
+    color: var(--color-success);
+}
+
+.toast.error {
+    border-color: var(--color-error);
+    color: var(--color-error);
+}
+
+/* ========================================
+   Responsive Design
+   ======================================== */
+
+@media (max-width: 768px) {
+    h1 {
+        font-size: 2rem;
+    }
+
+    h2 {
+        font-size: 1.5rem;
+    }
+
+    h3 {
+        font-size: 1.1rem;
+    }
+
+    .header-container {
+        flex-direction: column;
+        gap: var(--spacing-md);
+    }
+
+    .nav-primary ul {
+        justify-content: center;
+        gap: var(--spacing-md);
+    }
+
+    .hero {
+        grid-template-columns: 1fr;
+        padding: var(--spacing-xl) var(--spacing-lg);
+    }
+
+    .hero-content h2 {
+        font-size: 1.75rem;
+    }
+
+    .featured-editorial,
+    .featured-deal {
+        grid-template-columns: 1fr;
+    }
+
+    .featured-editorial .editorial-image,
+    .featured-editorial .editorial-content {
+        grid-column: 1;
+    }
+
+    .featured-deal .deal-image {
+        grid-column: 1;
+    }
+
+    .featured-deal .deal-content {
+        grid-column: 1;
+        padding-top: var(--spacing-sm);
+    }
+
+    .form-group {
+        flex-direction: column;
+    }
+
+    .footer-bottom {
+        flex-direction: column;
+        align-items: flex-start;
+    }
+
+    .footer-legal {
+        flex-wrap: wrap;
+    }
